<?php
// Public Midtrans notification endpoint. Configure this URL in Midtrans MAP.
require_once __DIR__.'/../config/koneksi.php';require_once __DIR__.'/../config/tahap4.php';
header('Content-Type: application/json; charset=utf-8');
try{$cfg=t4_midtrans_config();if($cfg['signature_secret']===''){http_response_code(503);echo json_encode(['status'=>'not_configured']);exit;}$raw=file_get_contents('php://input');$data=json_decode($raw,true);if(!is_array($data)){http_response_code(400);echo json_encode(['status'=>'invalid_json']);exit;}
$orderId=(string)($data['order_id']??'');$statusCode=(string)($data['status_code']??'');$gross=(string)($data['gross_amount']??'');$signature=(string)($data['signature_key']??'');$expected=hash('sha512',$orderId.$statusCode.$gross.$cfg['signature_secret']);if($orderId===''||$signature===''||!hash_equals($expected,$signature)){http_response_code(401);echo json_encode(['status'=>'invalid_signature']);exit;}
$q=$pdo->prepare("SELECT p.*,i.id invoice_id,i.pesanan_id,i.total_tagihan,i.status invoice_status FROM pembayaran p JOIN invoice i ON i.id=p.invoice_id WHERE p.kode_pembayaran=? AND p.provider='midtrans' LIMIT 1");$q->execute([$orderId]);$p=$q->fetch();if(!$p){http_response_code(404);echo json_encode(['status'=>'payment_not_found']);exit;}
$eventId=substr((string)($data['transaction_id']??$orderId).':'.$statusCode.':'.($data['transaction_status']??'unknown'),0,180);$pdo->beginTransaction();$ins=$pdo->prepare("INSERT IGNORE INTO pembayaran_webhook (pembayaran_id,provider,provider_event_id,event_type,signature_valid,payload,status_proses) VALUES (?,'midtrans',?,?,1,?,'Diproses')");$ins->execute([$p['id'],$eventId,(string)($data['transaction_status']??'notification'),$raw]);if($ins->rowCount()===0){$pdo->commit();echo json_encode(['status'=>'duplicate']);exit;}
$received=(float)$gross;$expectedAmount=(float)$p['jumlah'];if(abs($received-$expectedAmount)>0.01){$pdo->prepare("UPDATE pembayaran_webhook SET status_proses='Gagal',error_message='Gross amount mismatch',processed_at=NOW() WHERE provider='midtrans' AND provider_event_id=?")->execute([$eventId]);$pdo->commit();http_response_code(422);echo json_encode(['status'=>'amount_mismatch']);exit;}
$tx=(string)($data['transaction_status']??'');$fraud=(string)($data['fraud_status']??'');$success=($tx==='settlement')||($tx==='capture'&&($fraud===''||$fraud==='accept'));
if($success){$duplicate=($p['invoice_status']==='Lunas' && $p['status']!=='Berhasil');$rawStatus=$duplicate?'duplicate_payment_review':$tx;$pdo->prepare("UPDATE pembayaran SET status='Berhasil',provider_reference=?,payment_type=?,raw_status=?,dibayar_at=COALESCE(dibayar_at,NOW()) WHERE id=? AND status<>'Berhasil'")->execute([(string)($data['transaction_id']??''),(string)($data['payment_type']??''),$rawStatus,$p['id']]);if(!$duplicate){$pdo->prepare("UPDATE invoice SET status='Lunas',lunas_at=COALESCE(lunas_at,NOW()) WHERE id=? AND status<>'Lunas'")->execute([$p['invoice_id']]);$pdo->prepare("UPDATE pesanan SET status=CASE WHEN lamaran_id IS NOT NULL AND jenis_pelaksanaan='online' THEN 'Selesai' ELSE status END,status_pembayaran='Berhasil',status_pekerjaan=CASE WHEN lamaran_id IS NOT NULL AND jenis_pelaksanaan='online' THEN 'Selesai' WHEN status_pekerjaan='Menunggu Pembayaran' THEN 'Siap Dikerjakan' ELSE status_pekerjaan END,completed_at=CASE WHEN lamaran_id IS NOT NULL AND jenis_pelaksanaan='online' THEN COALESCE(completed_at,NOW()) ELSE completed_at END WHERE id=?")->execute([$p['pesanan_id']]);$orderQ=$pdo->prepare('SELECT pembeli_id,pekerja_id,kode_pesanan,lamaran_id,jenis_pelaksanaan FROM pesanan WHERE id=?');$orderQ->execute([$p['pesanan_id']]);$order=$orderQ->fetch();if($order){notify($pdo,(int)$order['pembeli_id'],'pembayaran','Pembayaran berhasil','Pembayaran pesanan '.$order['kode_pesanan'].' telah dikonfirmasi.','/penyedia/tahap4-pesanan.php?id='.$p['pesanan_id']);if(!empty($order['lamaran_id']) && $order['jenis_pelaksanaan']==='online'){t4_credit_worker_after_completion($pdo,(int)$p['pesanan_id'],null); }else{notify($pdo,(int)$order['pekerja_id'],'pembayaran','Pesanan siap dikerjakan','Pembayaran pesanan '.$order['kode_pesanan'].' telah diterima.','/pekerja/tahap4-pesanan.php?id='.$p['pesanan_id']);}}}else{$admins=$pdo->query("SELECT id FROM users WHERE role='admin'")->fetchAll(0);foreach($admins as $adminId){notify($pdo,(int)$adminId,'pembayaran','Perlu pemeriksaan pembayaran ganda','Pembayaran '.$orderId.' berhasil setelah invoice sudah lunas. Periksa dan proses refund jika diperlukan.','/admin/tahap4-transaksi.php');}}}
elseif($tx==='expire'){$pdo->prepare("UPDATE pembayaran SET status='Kedaluwarsa',raw_status=? WHERE id=? AND status<>'Berhasil'")->execute([$tx,$p['id']]);$pdo->prepare("UPDATE pesanan SET status_pembayaran='Kedaluwarsa' WHERE id=? AND status_pembayaran<>'Berhasil'")->execute([$p['pesanan_id']]);}
elseif(in_array($tx,['deny','cancel'],true)){$pdo->prepare("UPDATE pembayaran SET status='Gagal',raw_status=? WHERE id=? AND status<>'Berhasil'")->execute([$tx,$p['id']]);$pdo->prepare("UPDATE pesanan SET status_pembayaran='Gagal' WHERE id=? AND status_pembayaran<>'Berhasil'")->execute([$p['pesanan_id']]);}
else{$pdo->prepare("UPDATE pembayaran SET status='Menunggu',raw_status=? WHERE id=? AND status<>'Berhasil'")->execute([$tx,$p['id']]);}
$pdo->prepare("UPDATE pembayaran_webhook SET status_proses='Berhasil',processed_at=NOW() WHERE provider='midtrans' AND provider_event_id=?")->execute([$eventId]);$pdo->commit();http_response_code(200);echo json_encode(['status'=>'ok']);
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Midtrans notification: '.$e->getMessage());http_response_code(500);echo json_encode(['status'=>'error']);}
